    setFloorPlan: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @example lm_a */
                landmarkId: components["parameters"]["LandmarkId"];
                /**
                 * @description 階(1 = 1 階、地下は負)
                 * @example 1
                 */
                floor: number;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                /**
                 * @example {
                 *       "plan": {
                 *         "viewBox": "0 0 400 240",
                 *         "d": "M10 10 H390 V230 H10 Z M200 10 V230"
                 *       },
                 *       "bounds": {
                 *         "north": 37.4248,
                 *         "south": 37.4244,
                 *         "east": 138.7782,
                 *         "west": 138.7776
                 *       }
                 *     }
                 */
                "application/json": components["schemas"]["FloorPlanInput"];
            };
        };
        responses: {
            /** @description 登録した見取り図 */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "floor": 1,
                     *       "plan": {
                     *         "viewBox": "0 0 400 240",
                     *         "d": "M10 10 H390 V230 H10 Z M200 10 V230"
                     *       },
                     *       "bounds": {
                     *         "north": 37.4248,
                     *         "south": 37.4244,
                     *         "east": 138.7782,
                     *         "west": 138.7776
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["FloorPlan"];
                };
            };
            400: components["responses"]["BadRequest"];
            401: components["responses"]["Unauthorized"];
            404: components["responses"]["NotFound"];
            /** @description 見取り図の図形が大きすぎる(本文 1 MB まで。API-21) */
            413: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "code": "payload_too_large",
                     *       "message": "見取り図は 1 MB 以下にしてください"
                     *     }
                     */
                    "application/problem+json": components["schemas"]["Error"];
                };
            };
            500: components["responses"]["InternalError"];
        };
    };
    removeFloorPlan: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @example lm_a */
                landmarkId: components["parameters"]["LandmarkId"];
                /**
                 * @description 階(1 = 1 階、地下は負)
                 * @example 1
                 */
                floor: number;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description 消した */
            204: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            401: components["responses"]["Unauthorized"];
            /** @description 指定した建物か、その階の見取り図が無い */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "code": "not_found",
                     *       "message": "建物 lm_a の 1 階の見取り図は見つかりません"
                     *     }
                     */
                    "application/problem+json": components["schemas"]["Error"];
                };
            };
            500: components["responses"]["InternalError"];
        };
    };
